#!/usr/bin/env bash
# Derive an immutable, credential-free dependency adapter from the production action.
set -euo pipefail
root="$(cd "$(dirname "$0")/../.." && pwd)"
source="${1:-$root/actions/create-issues-from-todos/action.yaml}"
destination="${2:-$root/.github/actions/test-todo-default-fixture/action.yaml}"
work="$(mktemp -d)"
trap 'rm -rf "$work"' EXIT
yq -o=json '.' "$source" >"$work/source.json"
jq '
  .name = "Internal TODO default-path fixture" |
  .description = "Generated offline dependencies for the complete TODO default-path replay" |
  .inputs["fixture-skip-app-token"] = {
    description:"Deliberately skip the offline token dependency for the refusal control",
    required:false, default:"false"} |
  .runs.steps |= map(
    if has("run") then
      .run |= (split("${GITHUB_ACTION_PATH}/../../") | join("${GITHUB_ACTION_PATH}/../../../"))
    else . end |
    if .id == "app-token" then
      .env = {CLIENT_ID:.with["client-id"], APP_ID:.with["app-id"],
        APP_PRIVATE_KEY:.with["private-key"], PROJECT_PERMISSION:.with["permission-organization-projects"],
        OPTIONAL_PROJECT_AUTH:"${{ inputs.optional-project-auth }}", PROJECT:"${{ inputs.project }}",
        ACTION_SCRIPT:"${{ github.action_path }}/../../../.github/tests/todo-production-default-fixture.sh"} |
      .if = ("${{ (" + (.if | ltrimstr("${{ ") | rtrimstr(" }}")) +
        ") && inputs.fixture-skip-app-token != \u0027true\u0027 }}") |
      del(.uses, .with) | .shell = "bash" | .run = "bash \"$ACTION_SCRIPT\" app-token"
    elif (.uses // "" | startswith("actions/checkout@")) then
      del(.uses, .with) | .shell = "bash" |
      .run = "echo Offline checkout dependency: no workspace changes"
    else . end)
' "$work/source.json" >"$work/fixture.json"
mkdir -p "$(dirname "$destination")"
{
  printf '# Generated by .github/scripts/generate-todo-default-action.sh; do not edit.\n'
  yq -P '.' "$work/fixture.json"
} >"$destination"
